export const WEB_JS = "// Shared appearance preferences; never stores credentials.\n(function(){\n  var root=document.documentElement;\n  function read(k){try{return localStorage.getItem(k)}catch(_){return null}}\n  function save(k,v){try{localStorage.setItem(k,v)}catch(_){}}\n  var explicitLanguage=new URLSearchParams(location.search).get('lang');\n  if(explicitLanguage==='zh'||explicitLanguage==='en')save('publy-lang-override-v2',explicitLanguage);\n  var language=explicitLanguage||read('publy-lang-override-v2');\n  if(language!=='zh'&&language!=='en')language=(navigator.language||'en').startsWith('zh')?'zh':'en';\n  function lang(v){root.lang=v==='zh'?'zh-CN':'en';document.querySelectorAll('[data-switch]').forEach(function(b){b.setAttribute('aria-pressed',String(b.dataset.switch===v))})}\n  if(document.querySelector('[data-switch]'))lang(language);\n  document.querySelectorAll('[data-switch]').forEach(function(b){b.addEventListener('click',function(){lang(b.dataset.switch);save('publy-lang-override-v2',b.dataset.switch);var u=new URL(location.href);u.searchParams.set('lang',b.dataset.switch);history.replaceState(null,'',u.pathname+u.search+u.hash)})});\n  var theme=read('publy-theme');if(theme==='dark'||theme==='light')root.dataset.theme=theme;\n  document.querySelectorAll('[data-theme-switch]').forEach(function(b){b.setAttribute('aria-pressed',String(root.dataset.theme?root.dataset.theme==='dark':matchMedia('(prefers-color-scheme:dark)').matches));b.addEventListener('click',function(){var dark=root.dataset.theme?root.dataset.theme==='dark':matchMedia('(prefers-color-scheme:dark)').matches;root.dataset.theme=dark?'light':'dark';save('publy-theme',root.dataset.theme);b.setAttribute('aria-pressed',String(!dark))})});\n})();\n";
export const SETUP_TEMPLATE = "<!doctype html><html lang=\"en\" class=\"publy-web\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Connect WeChat · Publy</title><style>__WEB_CSS__</style></head><body><main class=\"pw-wrap\"><nav class=\"pw-nav\" aria-label=\"Publy\"><a href=\"https://publy.jrtx.site/\">Publy</a><div class=\"pw-actions\"><a href=\"/hosted\"><span data-lang=\"en\">Account & access</span><span data-lang=\"zh\">账户与权益</span></a><button type=\"button\" class=\"secondary\" data-switch=\"en\">EN</button><button type=\"button\" class=\"secondary\" data-switch=\"zh\">中文</button><button type=\"button\" class=\"secondary\" data-theme-switch aria-pressed=\"false\"><span data-lang=\"en\">Light / dark</span><span data-lang=\"zh\">亮 / 暗</span></button></div></nav>\n<h1><span data-lang=\"en\">Connect your Official Account</span><span data-lang=\"zh\">连接你的公众号</span></h1><p class=\"pw-muted\"><span data-lang=\"en\">Three steps. Checking the connection never creates or publishes a draft.</span><span data-lang=\"zh\">分三步完成。检查连接不会创建草稿，也不会公开发布。</span></p>\n<div class=\"pw-warning\"><span data-lang=\"en\">Check your account’s official draft API permission before paying. A successful credential check alone does not prove draft permission. Hosted purchases are not generally open.</span><span data-lang=\"zh\">付款前先确认公众号具备官方草稿接口权限。凭据校验成功并不代表具有草稿接口权限。托管购买尚未全面开放。</span></div>\n<section class=\"pw-step\"><h2><span data-lang=\"en\">1 · Restore your Publy account</span><span data-lang=\"zh\">1 · 恢复 Publy 账户</span></h2><form id=\"restore\"><label for=\"api-key\">Publy API Key</label><input id=\"api-key\" type=\"password\" autocomplete=\"off\" required><p class=\"pw-muted\"><span data-lang=\"en\">Use the key saved when your account was created. This is not your WeChat AppSecret.</span><span data-lang=\"zh\">填写开户时保存的 Key，不是公众号的 AppSecret。</span></p><div class=\"pw-actions\"><button id=\"restore-button\" type=\"submit\"><span data-lang=\"en\">Check my account</span><span data-lang=\"zh\">查看我的账户</span></button><button type=\"button\" id=\"forget\" class=\"secondary\"><span data-lang=\"en\">Clear this tab</span><span data-lang=\"zh\">清除此标签页凭据</span></button></div></form><p id=\"session-state\" role=\"status\" class=\"pw-feedback\" aria-live=\"polite\"></p><p id=\"account-list\" class=\"pw-config\"></p></section>\n<section class=\"pw-step\"><h2><span data-lang=\"en\">2 · Add this service’s IP to WeChat</span><span data-lang=\"zh\">2 · 在微信中添加本服务的 IP</span></h2><p><span data-lang=\"en\">Server egress IP (not your computer’s IP):</span><span data-lang=\"zh\">服务器出口 IP（不是你电脑的 IP）：</span> <strong id=\"egress-ip\">__PUBLIC_IP__</strong></p><div class=\"pw-actions\"><button type=\"button\" id=\"copy-ip\" class=\"secondary\"><span data-lang=\"en\">Copy server IP</span><span data-lang=\"zh\">复制服务器 IP</span></button><a href=\"https://publy.jrtx.site/wechat.html\"><span data-lang=\"en\">Open the step-by-step guide →</span><span data-lang=\"zh\">打开逐步操作指南 →</span></a></div><p><span data-lang=\"en\">Open the official <a href=\"https://mp.weixin.qq.com/\" target=\"_blank\" rel=\"noopener noreferrer\">WeChat Official Accounts Platform</a> with an administrator’s account. Find the API IP whitelist in the developer settings; if redirected, use the official developer platform linked there. Add one IP on a new line and keep existing entries.</span><span data-lang=\"zh\">用管理员身份打开官方<a href=\"https://mp.weixin.qq.com/\" target=\"_blank\" rel=\"noopener noreferrer\">微信公众号平台</a>。在开发设置中找到 API IP 白名单；若后台提示迁移，请从其链接进入官方开发者平台。另起一行添加本页 IP，保留已有条目。</span></p><p class=\"pw-muted\"><span data-lang=\"en\">Do not change login security IPs, business domains or JS domains. Do not reset AppSecret just to follow this guide.</span><span data-lang=\"zh\">不要改登录安全 IP、业务域名或 JS 接口安全域名，也不要为了跟随教程重置 AppSecret。</span></p></section>\n<section class=\"pw-step card\"><h2><span data-lang=\"en\">3 · Check and connect</span><span data-lang=\"zh\">3 · 检查并连接</span></h2><form id=\"bind\"><label for=\"account-name\"><span data-lang=\"en\">Account nickname (shown in Obsidian)</span><span data-lang=\"zh\">公众号昵称（在 Obsidian 中显示）</span></label><input id=\"account-name\" maxlength=\"40\" required><label for=\"app-id\">WeChat AppID</label><input id=\"app-id\" autocomplete=\"off\" required><label for=\"app-secret\">WeChat AppSecret</label><input id=\"app-secret\" type=\"password\" autocomplete=\"off\" required><p class=\"pw-muted\"><span data-lang=\"en\">Connecting sends these WeChat credentials to this Publy server for validation and storage. Only use a server you trust. AppSecret is not saved in browser storage.</span><span data-lang=\"zh\">连接时，公众号凭据将发送至当前 Publy 服务器进行校验并保存。只在你信任的服务中操作；AppSecret 不写入浏览器存储。</span></p><button type=\"submit\" id=\"bind-button\" disabled><span data-lang=\"en\">Check and connect · no draft created</span><span data-lang=\"zh\">检查并连接 · 不创建草稿</span></button></form><p id=\"bind-state\" class=\"pw-feedback\" role=\"status\" aria-live=\"polite\"></p></section>\n<section class=\"pw-step\"><h2><span data-lang=\"en\">Next · Configure Obsidian</span><span data-lang=\"zh\">接下来 · 配置 Obsidian</span></h2><p><span data-lang=\"en\">Open Settings → Publy. Server address:</span><span data-lang=\"zh\">打开「设置 → Publy」。服务器地址：</span> <strong id=\"server-url\" class=\"pw-config\"></strong></p><p><span data-lang=\"en\">Paste your Publy API Key, select the connected account, then test the connection. Preview a non-sensitive note first. Draft submission always needs your explicit confirmation.</span><span data-lang=\"zh\">填入 Publy API Key，选择已连接的公众号，再测试连接。先预览一篇不含敏感信息的笔记；投递草稿需要你明确确认。</span></p><a href=\"https://publy.jrtx.site/wechat.html\"><span data-lang=\"en\">First draft, recovery and troubleshooting →</span><span data-lang=\"zh\">第一篇草稿、恢复与故障排查 →</span></a></section></main><script>__WEB_JS__</script><script>__SETUP_JS__</script></body></html>";
